// Generated by design/build_site.py (build_sw): keeps the site's files in the browser for instant return visits.
const CACHE = 'site-bf932a0ace80';
self.addEventListener('install', () => self.skipWaiting());
self.addEventListener('activate', (e) => e.waitUntil((async () => {
  for (const k of await caches.keys()) if (k !== CACHE) await caches.delete(k);
  await self.clients.claim();
})()));
self.addEventListener('fetch', (e) => {
  const r = e.request;
  const url = new URL(r.url);
  if (r.method !== 'GET' || url.origin !== location.origin || r.headers.has('range') || url.pathname.endsWith('.pdf') || url.pathname === '/sw.js') return;
  e.respondWith(r.mode === 'navigate' ? fromNetwork(r) : fromCopy(r));
});
// a page: the network's, kept for offline; offline, the kept one (or the homepage)
async function fromNetwork(r) {
  const cache = await caches.open(CACHE);
  try {
    const res = await fetch(r);
    if (res.ok) cache.put(r, res.clone());
    return res;
  } catch (err) {
    return (await cache.match(r, { ignoreSearch: true })) || (await cache.match('/')) || Response.error();
  }
}
// a file: the kept copy, or the network's, then kept. Fetched past the browser's own ten-minute cache (checked with
// the server), or a copy from before a release would be kept until the next one
async function fromCopy(r) {
  const cache = await caches.open(CACHE);
  const kept = await cache.match(r);
  if (kept) return kept;
  const res = await fetch(r, { cache: 'no-cache' });
  if (res.ok && res.type === 'basic') cache.put(r, res.clone());
  return res;
}
